"use strict";

function show() {
  console.log(this);
}

const api = {
  name: "attempt-api",
  show,
};

api.show();        // implicit — { name, show }
const detached = api.show;
detached();        // default — undefined (strict)

function parse(raw) {
  return `${this.provider}:${raw}`;
}

const lti = { provider: "lti" };
const oidc = { provider: "oidc" };

console.log(parse.call(lti, "jwt"));  // lti:jwt
console.log(parse.apply(oidc, ["jwt"])); // oidc:jwt

const bound = parse.bind(lti);
console.log(bound("jwt")); // lti:jwt — this locked

class Handler {
  constructor(id) {
    this.id = id;
  }
  // prototype method — this depends on call site
  handle() {
    return this.id;
  }
  // class field arrow — lexical this from construction
  handleArrow = () => {
    return this.id;
  };
}

const h = new Handler("h1");
const a = h.handle;
const b = h.handleArrow;

console.log(h.handle());    // h1
console.log(a());           // TypeError — undefined.id in strict class
console.log(b());           // h1 — arrow captured instance this

function Service(name) {
  this.name = name;
  this.run = function () {
    return this.name;
  };
}

const s = new Service("worker");
console.log(s.run()); // worker — implicit on s

const loose = s.run;
console.log(loose()); // undefined.name in strict — lost again

const obj = {
  x: 10,
  getX() { return this.x; },
  getXLater() {
    setTimeout(function () {
      console.log(this.x); // default binding — undefined.x
    }, 0);
    setTimeout(() => {
      console.log(this.x); // lexical — 10
    }, 0);
  },
};

obj.getXLater();
